    correction: [{"quoi":"القاعدة","math":"التواتر هو التكرار مقسوما على التكرار الجملي ; و النسبة المائوية هي التواتر في 100 ; و قيس الزاوية هو التواتر في 360"},{"quoi":"التكرار الجملي","math":"<span dir=\"ltr\" class=\"expr\">N = 60</span>"},{"quoi":"التواتر الأوّل","math":"<span dir=\"ltr\" class=\"expr\">fa = <span class=\"frac\"><span class=\"num\">19</span><span class=\"den\">60</span></span></span>"},{"quoi":"أي بالنسبة المائوية","math":"<span dir=\"ltr\" class=\"expr\">pa = <span class=\"frac\"><span class=\"num\">95</span><span class=\"den\">3</span></span></span>"},{"quoi":"نتحقّق أنّ مجموع النسب يساوي 100","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">95</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">100</span><span class=\"den\">3</span></span> + 35 = 100</span>"},{"quoi":"الزاوية المطلوبة","math":"<span dir=\"ltr\" class=\"expr\">gc = 360 × <span class=\"frac\"><span class=\"num\">21</span><span class=\"den\">60</span></span></span>"},{"quoi":"أي","math":"<span dir=\"ltr\" class=\"expr\">gc = 126</span>"},{"quoi":"النتيجة","math":"قيس الزاوية الموافقة هو 126 درجة"}],
